        for(const auto& id:common_catalog->organization_ids){common.state().wallets.insert(id+".wallet",{id+".wallet",{Owner::Kind::organization,id,{}},1,{}});OrganizationRecord organization;organization.id=id;organization.kind="local";organization.headquarters_site="town";organization.office_ids={id+".office"};catalog.organizations.insert(id,organization);OfficeState office;office.id=id+".office";office.organization_id=id;office.holder_actor_id="mayor";office.grant_ids={id+".grant"};catalog.offices.insert(office.id,office);Grant grant;grant.id=id+".grant";grant.office_id=office.id;grant.allowed_command_kinds={"organization_offer_membership","contract_executor","claim_need"};grant.scopes={{ScopeRef::Kind::site,"town"}};grant.wallet_ids={id+".wallet"};grant.amount_limit=100;grant.may_delegate=true;grant.continuity_policy_id="continue_under_organization";catalog.grants.insert(grant.id,grant);MembershipTerms terms;terms.id=id+".terms";terms.organization_id=id;terms.site_id="town";terms.member_policy_id="member.policy";terms.payer_wallet_id=id+".wallet";terms.wage_rate_profile_id="salary";terms.wage_period_ticks=2;terms.offer_duration_ticks=10;catalog.membership_terms.insert(terms.id,terms);}
