// 半钱来自完整有效账期，终态1钱原债和再次任职的零余数不能互相复活。
void wage_lifecycle(){Fixture f;auto source=f.acceptance_source();auto joined=need(f.join(source));auto* obligation=f.economy.obligations.find(joined.obligation_id);check(f.org.members.size()==1&&f.org.duties.size()==1&&f.economy.obligations.size()==1,"join creates real unique owners");auto joined_view=organization_dynamic_fact(f.org,f.org.members.find(joined.member_episode_id)->last_fact_id);check(joined_view&&joined_view->publicly_visible&&joined_view->rule_version=="named_membership_v1"&&!joined_view->obligation&&std::any_of(joined_view->participants.begin(),joined_view->participants.end(),[](const FactParticipant& p){return p.subject.kind==SubjectKind::actor&&p.subject.id=="mayor";}),"joined status includes real inviter without private wage amount");check(obligation->next_due_tick==2&&f.common.wallet("worker.wallet")->balance==0,"first due starts at acceptance plus period");f.step();check(f.economy.arrears.empty(),"no wage before effective period");f.restore();f.step();check(f.common.wallet("worker.wallet")->balance==1&&*f.economy.obligation_remainders.find(joined.obligation_id)==1,"exact integer wage carries one half");need(f.leave());f.validate();const auto& terminal=f.economy.membership_terminal_fractions.rows().front().second;check(terminal.original_numerator==1&&terminal.denominator==2&&terminal.compensation_numerator==1&&terminal.integer_due==1,"terminal records original and compensation fractions");check(need(outstanding_arrears(f.economy,joined.obligation_id))==1&&!f.economy.obligations.find(joined.obligation_id)->active,"short terminal coin becomes original employer arrear");check(!f.leave().ok,"duplicate departure cannot pay again");f.restore();f.fund("city",2);auto rejoined=need(f.join(f.acceptance_source()));check(rejoined.member_episode_id!=joined.member_episode_id&&f.org.members.size()==2,"rejoin appends episode retaining departed history");check(active_membership_episode(f.org,"worker","city")->id==rejoined.member_episode_id,"active episode lookup skips old departed record");OrganizationAccess access(f.common,f.org,f.catalog,f.economy);check(access.actor_accepts_duty("worker","city"),"new episode accepts actual old contract duty interface");f.step();check(need(outstanding_arrears(f.economy,joined.obligation_id))==0&&f.common.wallet("worker.wallet")->balance==2,"old debt pays after rejoin from old obligation");check(*f.economy.obligation_remainders.find(rejoined.obligation_id)==0,"rejoin starts fresh zero remainder");f.step();check(f.common.wallet("worker.wallet")->balance==3,"only current episode earns next period");f.restore();}
// 零时间及尚未到期没有尾差补偿；一个完整整数账期也不凭空生补偿。
void no_terminal_reward(){Fixture zero;auto joined=need(zero.join(zero.acceptance_source()));need(zero.leave());zero.validate();check(zero.common.wallet("worker.wallet")->balance==0&&zero.economy.arrears.empty(),"zero-time leave receives no money");check(zero.economy.membership_terminal_fractions.rows().front().second.integer_due==0,"zero-time terminal has no compensation");zero.restore();zero.step();check(zero.economy.arrears.empty(),"restored ended obligation stays ended");Fixture before;need(before.join(before.acceptance_source()));before.step();need(before.leave());before.validate();check(before.economy.arrears.empty(),"elapsed partial first period does not invent accrued wage");Fixture integer;integer.economy_catalog.rates.find("salary")->numerator=2;integer.economy_catalog.rates.find("salary")->denominator=1;integer.fund("city",1);need(integer.join(integer.acceptance_source()));integer.step();integer.step();need(integer.leave());integer.validate();check(integer.economy.membership_terminal_fractions.rows().front().second.integer_due==0&&integer.common.wallet("worker.wallet")->balance==2,"integer rate has no terminal fraction");(void)joined;}
// 真实责任读口可以阻挡无action的旧任务；仅欠钱不能阻挡离开。
void blockers_and_autonomy(){Fixture f;auto source=f.acceptance_source();f.release.blockers={{MembershipReleaseBlockerKind::task_execution,"old.task",""}};check(!f.join(source).ok&&f.org.members.empty()&&f.economy.obligations.empty(),"pending old task blocks acceptance without action");f.release.blockers.clear();auto joined=need(f.join(source));f.release.blockers={{MembershipReleaseBlockerKind::entrusted_cargo,"old.cargo",""}};need(f.leave());auto awaiting=organization_dynamic_fact(f.org,f.org.members.find(joined.member_episode_id)->last_fact_id);check(awaiting&&!awaiting->publicly_visible&&awaiting->participants.size()==3&&!awaiting->obligation,"awaiting release remains known to actual parties without public wage details");check(f.org.members.find(joined.member_episode_id)->response==MemberResponse::awaiting_release&&f.economy.obligations.find(joined.obligation_id)->active,"entrusted cargo retains member and existing wage obligation");need(reconcile_named_membership(f.common,f.org,f.catalog,f.economy,f.economy_catalog,f.activity,f.release,f.common.tick()));check(f.org.members.find(joined.member_episode_id)->response==MemberResponse::awaiting_release,"reconcile cannot erase cargo responsibility");f.release.blockers.clear();need(reconcile_named_membership(f.common,f.org,f.catalog,f.economy,f.economy_catalog,f.activity,f.release,f.common.tick()));f.validate();check(f.org.members.find(joined.member_episode_id)->response==MemberResponse::departed,"owner completion permits release");Fixture debt;auto other=need(debt.join(debt.acceptance_source()));debt.step();debt.step();debt.step();debt.step();need(reconcile_organization(debt.common,debt.org,debt.catalog,debt.economy,debt.activity,debt.common.tick()));check(debt.org.members.find(other.member_episode_id)->response==MemberResponse::serving,"new profile does not autonomously compete with Director");need(debt.leave());debt.validate();check(need(outstanding_arrears(debt.economy,other.obligation_id))==2,"old integer debt never binds person");}
// 旧整数账期先付，尾差即使同tick也排在原债后；新雇主绝不代付旧雇主的债。
void terminal_payment_and_priority(){Fixture immediate;auto joined=need(immediate.join(immediate.acceptance_source()));immediate.step();immediate.step();immediate.fund("city",1);need(immediate.leave());immediate.validate();check(immediate.common.wallet("city.wallet")->balance==0&&immediate.common.wallet("worker.wallet")->balance==2&&need(outstanding_arrears(immediate.economy,joined.obligation_id))==0,"terminal coin debits actual original wallet");Fixture old;auto employed=need(old.join(old.acceptance_source()));for(int i=0;i<6;++i)old.step();need(old.leave());old.validate();const auto receipt=old.economy.membership_terminal_fractions.rows().front().second;check(need(outstanding_arrears(old.economy,employed.obligation_id))==4,"old integer debts plus one exact terminal coin remain");old.fund("city",2);old.step();check(old.economy.arrears.find(receipt.arrear_id)->paid_amount==0&&need(outstanding_arrears(old.economy,employed.obligation_id))==2,"earliest original debt consumes funds first");old.fund("city",1);old.step();check(old.economy.arrears.find(receipt.arrear_id)->paid_amount==0&&need(outstanding_arrears(old.economy,employed.obligation_id))==1,"same tick original integer debt precedes compensation");auto new_job=need(old.join(old.acceptance_source("guild")));need(invalidate_office(old.common,old.org,old.catalog,"city.office",old.common.tick(),{}));old.fund("city",1);old.step();old.validate();check(old.economy.arrears.find(receipt.arrear_id)->paid_amount==1&&old.common.wallet("guild.wallet")->balance==1,"vacant old employer settles its own debt after cross-organization join");check(old.economy.obligations.find(new_job.obligation_id)->next_due_tick==10&&old.economy.membership_wage_bindings.find(new_job.wage_binding_id)->credited_periods==0,"new employer has independent first period and no inherited debt");}
// 释放中的旧债支付晚失败仍恢复真实钱包；账本与成员不留下半个终态。
void release_rollback(){Fixture f;auto joined=need(f.join(f.acceptance_source()));for(int i=0;i<4;++i)f.step();f.fund("city",2);f.common.state().next_instance_id=INT64_MAX-1;const auto ids=f.common.state().next_instance_id;auto org=encode_organization_state(f.org,true);auto economy=encode_local_economy_state(f.economy,false,true);const auto payer=f.common.wallet("city.wallet")->balance;const auto payee=f.common.wallet("worker.wallet")->balance;auto failed=f.leave();check(!failed.ok&&f.common.state().next_instance_id==ids&&f.common.wallet("city.wallet")->balance==payer&&f.common.wallet("worker.wallet")->balance==payee,"late release payment receipt failure restores all wallet changes and IDs");check(compare_boundary(org,encode_organization_state(f.org,true)).exact()&&compare_boundary(economy,encode_local_economy_state(f.economy,false,true)).exact(),"late release preserves active member and exact prior debts");check(f.economy.obligations.find(joined.obligation_id)->active,"failed release cannot stop future obligation");}
// 旧目录成员与新episode共用一张成员表；同tick再加入不能复活目录工资。
void seed_departure_rejoin(){Fixture f;OrgDuty duty;duty.id="seed.duty";duty.organization_id="city";duty.actor_id="worker";duty.policy_id="member.policy";duty.obligation_ids={"seed.salary"};OrgMemberState member;member.id="seed.member";member.organization_id="city";member.actor_id="worker";member.policy_id="member.policy";member.duty_ids={duty.id};f.catalog.members.insert(member.id,member);f.org.members.insert(member.id,member);f.catalog.duties.insert(duty.id,duty);f.org.duties.insert(duty.id,duty);RecurringObligation salary;salary.id="seed.salary";salary.principal={SubjectKind::organization,"city"};salary.beneficiary={SubjectKind::actor,"worker"};salary.source_wallet_or_inventory="city.wallet";salary.destination="worker.wallet";salary.rate_profile="salary";salary.authority_ref="seed.issuer";salary.period_ticks=2;salary.next_due_tick=2;f.economy_catalog.obligations.insert(salary.id,salary);f.economy=need(make_initial_local_economy(f.common,f.economy_catalog,0));f.catalog.institutional_issuers.insert("seed.issuer",{"seed.issuer","city","continue_under_organization",{salary.id},{"city.wallet"},100});f.validate();need(f.leave());check(!f.economy.obligations.find(salary.id)->active,"seed departure immediately stops only future old wage");need(f.join(f.acceptance_source()));f.step();f.step();check(f.economy.arrears.size()==1&&f.common.wallet("worker.wallet")->balance==1,"same tick seed-to-dynamic rejoin never duplicates wages");}
// 补足欠薪不自动替本人复工；只有同一有效episode的真实支付来源才能重新同意职责。
