int main(int argc,char** argv){try{if(argc==2){authored_membership_catalog(argv[1]);std::cout<<"NAMED_MEMBERSHIP_AUTHORED_CATALOG "<<checks<<" checks 0 failures\n";return 0;}wage_lifecycle();no_terminal_reward();blockers_and_autonomy();rollback_and_strict_sources();terminal_payment_and_priority();release_rollback();seed_departure_rejoin();paid_reassessment();withdrawal_provenance();std::cout<<"NAMED_MEMBERSHIP_LIFECYCLE "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& error){std::cerr<<"NAMED_MEMBERSHIP_LIFECYCLE FAIL "<<error.what()<<'\n';return 1;}}
